import { publicCatalogueRead, blockNativeCatalogueWrite } from "$publicApi/site-client";
import { PUBLIC_API_URL } from "$env/static/public";
import { readPublicSearch } from "$platform/latest-search";
import { HTTP } from "$lib";

export const Search = (searchParams: URLSearchParams, signal?: AbortSignal) => {
	if (Boolean(true)) return publicCatalogueRead<TagFeedResponse>("author.search", { query: searchParams, signal });
	if (signal) return readPublicSearch<TagFeedResponse>("/author", searchParams, signal);
	const http = new HTTP<TagFeedResponse>(`${PUBLIC_API_URL}/author${searchParams.toString()}`);
	return http.GET();
};

export const Get = (id: string) => {
	if (Boolean(true)) return publicCatalogueRead<Author>("author.get", { id });
	const http = new HTTP<Author>(`${PUBLIC_API_URL}/author/${id}`);
	return http.GET();
};

export const Create = (name: string) => {
	if (Boolean(true)) return blockNativeCatalogueWrite("Author.Create");
	const http = new HTTP<Author>(`${PUBLIC_API_URL}/author`, { name });
	http.setWithCredentials(true);
	return http.POST();
};

export interface UpdateAuthorRequest {
	name?: string;
	description?: string;

	twitter?: string;
	pixiv?: string;
	fanbox?: string;
	fantia?: string;
	skeb?: string;
	youtube?: string;
	website?: string;

	locked?: boolean;
	version: number;
}

export const Update = (id: string, payload: UpdateAuthorRequest) => {
	if (Boolean(true)) return blockNativeCatalogueWrite("Author.Update");
	const http = new HTTP<Author>(`${PUBLIC_API_URL}/author/${id}`, payload);
	http.setWithCredentials(true);
	return http.PUT();
};

export const Delete = (id: string) => {
	if (Boolean(true)) return blockNativeCatalogueWrite("Author.Delete");
	const http = new HTTP<Author>(`${PUBLIC_API_URL}/author/${id}`);
	http.setWithCredentials(true);
	return http.DELETE();
};
